{"command": "cat <<EOF > app/api/handlers.py
"""Request handlers. Handlers receive untrusted params and call app.services only."""

from app.services import users
import email_validator

def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user

def handle_validate_email(params: dict) -> tuple[int, dict]:
    email = params.get("email")
    if not isinstance(email, str):
        return 400, {"valid": False, "error": "invalid email"}

    try:
        # validate_email returns an object with 'email' (normalized)
        # We need to make sure the domain part is lower-cased.
        # email_validator does this by default if we call it correctly.
        validation = email_validator.validate_email(email, check_deliverability=False)
        return 200, {"valid": True, "email": validation.normalized}
    except email_validator.EmailNotValidError:
        return 400, {"valid": False, "error": "invalid email"}
EOF
